import { Request, Response } from 'express';
import { CreateProjectUseCase } from '../application/CreateProjectUseCase';
import { asString, bodyOf } from './requestValues';

export class ProjectController {
  constructor(private readonly createProject: CreateProjectUseCase) {}

  create = async (req: Request, res: Response): Promise<void> => {
    const project = await this.createProject.execute({ name: asString(bodyOf(req.body).name) });
    res.status(201).json(project);
  };
}

